CREATE TABLE IF NOT EXISTS kfzb_seasons(id BIGSERIAL PRIMARY KEY,season_no INTEGER NOT NULL UNIQUE,global_state SMALLINT NOT NULL DEFAULT 10,signup_opens_at TIMESTAMPTZ NOT NULL,qualifier_opens_at TIMESTAMPTZ NOT NULL,phase2_opens_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,min_level INTEGER NOT NULL,support_level INTEGER NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS kfzb_signups(season_id BIGINT NOT NULL REFERENCES kfzb_seasons(id) ON DELETE CASCADE,player_id BIGINT NOT NULL REFERENCES players(id) ON DELETE CASCADE,competitor_id BIGSERIAL,general_ids INTEGER[] NOT NULL,eliminated BOOLEAN NOT NULL DEFAULT false,saiqu_id INTEGER NOT NULL DEFAULT 0,synced_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(season_id,player_id),UNIQUE(season_id,competitor_id));
CREATE TABLE IF NOT EXISTS kfzb_matches(id BIGSERIAL PRIMARY KEY,season_id BIGINT NOT NULL REFERENCES kfzb_seasons(id) ON DELETE CASCADE,phase SMALLINT NOT NULL,layer_no INTEGER NOT NULL,round_no INTEGER NOT NULL,legacy_match_id INTEGER NOT NULL,player1_id BIGINT NOT NULL REFERENCES players(id),player2_id BIGINT NOT NULL REFERENCES players(id),battle_id BIGINT REFERENCES world_battle_handoffs(id),state SMALLINT NOT NULL DEFAULT 0,winner_player_id BIGINT REFERENCES players(id),starts_at TIMESTAMPTZ NOT NULL,deadline_at TIMESTAMPTZ NOT NULL,resolved_at TIMESTAMPTZ,UNIQUE(season_id,phase,layer_no,round_no,legacy_match_id));
CREATE TABLE IF NOT EXISTS kfzb_rewards(season_id BIGINT NOT NULL REFERENCES kfzb_seasons(id) ON DELETE CASCADE,player_id BIGINT NOT NULL REFERENCES players(id) ON DELETE CASCADE,wins INTEGER NOT NULL DEFAULT 0,losses INTEGER NOT NULL DEFAULT 0,reward_info JSONB NOT NULL DEFAULT '[]'::jsonb,done_num INTEGER NOT NULL DEFAULT 0,title TEXT,eliminated_layer INTEGER,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(season_id,player_id));
CREATE TABLE IF NOT EXISTS kfzb_settlement_ledger(match_id BIGINT PRIMARY KEY REFERENCES kfzb_matches(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
